/* ============================================================
   Texte in der Sprache der lernenden Person (de) zu
   data/core/grammar-reference.js
   Die Schlüssel verweisen auf die id der neutralen Schicht; Arrays
   werden nach Index zusammengeführt, ihre Länge muss also mit core
   übereinstimmen. Geprüft von scripts/parity.mjs.

   Die kontrastiven Hinweise sind gegen das Deutsche geschrieben, nicht
   aus dem Polnischen übersetzt: der Vergleichspunkt wechselt mit der
   Sprache der lesenden Person. Deutsch bringt beim Hilfsverb und bei
   den da-Formen viel mit und beim Kasus gar nichts.
   ============================================================ */
LINGUAI.addStrings("de", {
  "refsec:titles": [
    "Nomen und Artikel",
    "Adjektive",
    "Pronomen",
    "Verben — der Indikativ",
    "Verben — Konjunktiv und Konditional",
    "Imperativ, infinite Formen, das Passiv",
    "Präpositionen, Adverbien, Konnektoren",
    "Syntax und Text"
  ],
  "ref:g-nome-genere": {
    title: "Das Genus des Nomens",
    sub: "maskulin und feminin, Endungen -o / -a / -e",
    body: "<p>Italienisch kennt <b>kein Neutrum</b>. Genus an sich ist dir vertraut, aber jedes deutsche Neutrum muss neu einsortiert werden: <em>das Buch</em> wird <em>il libro</em> (m), <em>das Haus</em> wird <em>la casa</em> (f). Es gibt keine Regel dafür — das Genus gehört zum Wort und wird mit ihm gelernt.</p><h4>Drei Muster</h4><ul><li><b>-o</b> → maskulin: <em>il libro, il tavolo</em>. Ausnahmen: <em>la mano, la radio, la foto, la moto</em>.</li><li><b>-a</b> → feminin: <em>la casa, la porta</em>. Ausnahmen griechischer Herkunft: <em>il problema, il programma, il tema, il sistema, il clima</em> — im Deutschen ebenfalls maskulin, „der Problemfall\", „das Thema\" allerdings neutral.</li><li><b>-e</b> → maskulin <i>oder</i> feminin: <em>il fiore</em>, aber <em>la chiave</em>. Hier hilft die Endung nicht.</li></ul><h4>Endungen, die das Genus verraten</h4><ul><li><b>-zione, -sione, -tà, -tù, -ice</b> sind immer feminin: <em>la stazione, la città, la virtù, l'attrice</em>. Praktisch: <em>-zione</em> entspricht dem deutschen <em>-tion</em>, das ebenfalls feminin ist.</li><li><b>-ore, -ame, -ume</b> sind meist maskulin: <em>il colore, il bestiame, il costume</em>.</li><li>Lehnwörter übernehmen das Genus des Wortes, das sie ersetzen: <em>il computer</em> (calcolatore), <em>la mail</em> (posta).</li></ul><p class='callout callout--trap'>Der gute Trost: Italienisch hat zwar ein Genus weniger, dafür ist es an der Endung meistens ablesbar. Deutsch verlangt den Artikel als reine Gedächtnisleistung, Italienisch gibt dir in vier von fünf Fällen einen Hinweis.</p>"
  },
  "ref:g-nome-plurale": {
    title: "Der Plural",
    sub: "-i, -e und unveränderliche Nomen",
    body: "<p>Der Plural ändert die Endung. Und das ist alles: kein Umlaut, keine acht Klassen, kein <em>-er</em>, <em>-en</em>, <em>-s</em> je nach Wort. Nach dem deutschen Pluralsystem wirkt das italienische fast unhöflich einfach.</p><div class='table-wrap'><table class='gt'><thead><tr><th>Singular</th><th>Plural</th><th>Beispiel</th></tr></thead><tbody><tr><td>-o (m)</td><td class='it'>-i</td><td>il libro → i libri</td></tr><tr><td>-a (f)</td><td class='it'>-e</td><td>la casa → le case</td></tr><tr><td>-a (m)</td><td class='it'>-i</td><td>il problema → i problemi</td></tr><tr><td>-e (m/f)</td><td class='it'>-i</td><td>il fiore → i fiori; la chiave → le chiavi</td></tr></tbody></table></div><h4>Gar keine Änderung</h4><p>Wörter mit Betonung auf dem letzten Vokal (<em>la città, il caffè</em>), Lehnwörter (<em>il bar, lo sport</em>), gekürzte Wörter (<em>la foto, il cinema</em>) und Einsilber (<em>il re</em>). Nur der Artikel zeigt den Numerus.</p><h4>Rechtschreibung</h4><ul><li><b>-co / -go</b>: Betonung auf der vorletzten Silbe → <em>-chi / -ghi</em> (<em>il fuoco → i fuochi</em>); Betonung früher → <em>-ci / -gi</em> (<em>il medico → i medici</em>).</li><li><b>-ca / -ga</b>: immer <em>-che / -ghe</em> (<em>l'amica → le amiche</em>).</li><li><b>-cia / -gia</b>: das i bleibt nach Vokal (<em>la camicia → le camicie</em>), fällt nach Konsonant (<em>l'arancia → le arance</em>).</li></ul>"
  },
  "ref:g-articolo-det": {
    title: "Der bestimmte Artikel",
    sub: "il, lo, la, l', i, gli, le",
    body: "<p>Die Form hängt von Genus, Numerus und dem <b>ersten Laut</b> des folgenden Wortes ab. Sie hängt <b>nicht</b> vom Kasus ab: <em>il libro</em> bleibt <em>il libro</em>, ob es Subjekt oder Objekt ist. Nach der/den/dem/des ist das die größte Entlastung des ganzen Kapitels.</p><div class='table-wrap'><table class='gt'><thead><tr><th>Kontext</th><th>Sing.</th><th>Pl.</th></tr></thead><tbody><tr><td>m. + Konsonant</td><td class='it'>il</td><td>i</td></tr><tr><td>m. + s+Kons., z, gn, ps, x, y</td><td class='it'>lo</td><td>gli</td></tr><tr><td>m. + Vokal</td><td class='it'>l'</td><td>gli</td></tr><tr><td>f. + Konsonant</td><td class='it'>la</td><td>le</td></tr><tr><td>f. + Vokal</td><td class='it'>l'</td><td>le</td></tr></tbody></table></div><p>Der Artikel richtet sich nach dem, was <b>unmittelbar</b> folgt, nicht nach dem Nomen: <em>lo studente</em>, aber <em>il bravo studente</em>. Die Schwierigkeit ist also lautlich, nicht grammatisch.</p><h4>Wo Italienisch ihn braucht und Deutsch nicht</h4><ul><li>vor Ländern, Regionen, Flüssen, Bergen: <em>l'Italia, la Toscana, il Po</em> (nicht vor Städten)</li><li>bei Uhrzeiten und Daten: <em>sono le tre, il 5 maggio</em></li><li>bei Nomen im allgemeinen Sinn: <em>mi piace il caffè</em> — „ich mag Kaffee\", ohne Artikel im Deutschen</li><li>vor Wochentagen im Sinne von „jeden\": <em>il lunedì</em> = montags</li><li>bei Possessiva: <em>il mio libro</em>, wo Deutsch nur „mein Buch\" sagt</li></ul>"
  },
  "ref:g-articolo-indet": {
    title: "Unbestimmter Artikel und Teilungsartikel",
    sub: "un, uno, una, un' und del, della, dei…",
    body: "<p><b>Unbestimmt</b>: <em>un</em> (m + Konsonant und Vokal), <em>uno</em> (m + s+Kons., z), <em>una</em> (f + Konsonant), <em>un'</em> (f + Vokal).</p><p class='callout callout--trap'><b>un amico</b> ohne Apostroph (ein Mann) gegen <b>un'amica</b> mit Apostroph (eine Frau). Der Apostroph trägt hier das Genus, und er fällt leicht unter den Tisch.</p><p><b>Teilungsartikel</b> (di + bestimmter Artikel) drückt eine unbestimmte Menge aus: <em>del pane</em>, <em>dell'acqua</em>, <em>delle mele</em>. Deutsch hat dafür gar nichts und sagt einfach „Brot\", „Wasser\", „Äpfel\". Diese Lücke muss im Italienischen gefüllt werden — sie wegzulassen klingt abgehackt.</p><p>Bei Verneinung verschwindet er meist: <em>non ho pane</em>.</p><p>Einen Plural des unbestimmten Artikels gibt es nicht; das übernimmt der Teilungsartikel: <em>un libro → dei libri</em>.</p>"
  },
  "ref:g-articolo-omissione": {
    title: "Wann KEIN Artikel steht",
    sub: "Auslassungen und feste Wendungen",
    body: "<ul><li>nach <em>essere</em> bei Beruf oder Nationalität: <em>sono medico, sono tedesco</em> — genau wie „ich bin Arzt\" im Deutschen</li><li>vor Städtenamen und kleinen Inseln: <em>vado a Roma, a Capri</em></li><li>vor Demonstrativa und Fragewörtern: <em>questo libro, quanti anni hai?</em></li><li>vor einem einzelnen, nicht näher bestimmten Familienmitglied mit Possessiv: <em>mia madre</em>, aber <em>le mie sorelle</em></li><li>in festen Wendungen: <em>andare in vacanza, cercare lavoro, avere fame, a casa, in ufficio</em></li><li>nach <em>di</em> für Material und Zugehörigkeit: <em>un tavolo di legno, la casa di Marco</em></li></ul><p>In <b>C1</b> kommen Formeln dazu, die den Artikel vor dem Possessiv streichen: <em>a mio parere, a sua insaputa, a mio nome</em>.</p>"
  },
  "ref:g-nome-avanzato": {
    title: "Schwierige Plurale",
    sub: "Doppelformen und Komposita",
    body: "<h4>Zwei Plurale, zwei Bedeutungen</h4><p>Ein gutes Dutzend Nomen hat zwei Pluralformen mit verschiedenem Sinn: <em>l'osso → gli ossi</em> (einzelne Knochen, die man dem Hund gibt) und <em>le ossa</em> (das Skelett); <em>il filo → i fili</em> (Fäden, Drähte) und <em>le fila</em> (die Fäden einer Handlung); <em>il frutto → i frutti</em> (Früchte im Sinne von Ergebnissen) und <em>la frutta</em> (Obst); <em>il braccio → le braccia</em> (Arme des Körpers) und <em>i bracci</em> (Arme eines Krans).</p><h4>Komposita</h4><p>Hier liegt der große Unterschied: Deutsch schreibt zusammen und dekliniert nur das letzte Glied. Italienisch entscheidet von Fall zu Fall, welches Glied den Plural trägt.</p><ul><li>unverändert: <em>il doposcuola → i doposcuola</em></li><li>das zweite Glied ändert sich: <em>il cavolfiore → i cavolfiori</em>, <em>il capolavoro → i capolavori</em>, <em>l'asciugamano → gli asciugamani</em></li><li>das erste ändert sich: <em>il capofamiglia → i capifamiglia</em>, <em>il fico d'India → i fichi d'India</em></li><li>beide ändern sich: <em>la cassaforte → le casseforti</em>, <em>il bassofondo → i bassifondi</em></li></ul>"
  },
  "ref:g-agg-accordo": {
    title: "Die Adjektivangleichung",
    sub: "vier Endungen und zwei",
    body: "<p>Das Adjektiv richtet sich nach Genus und Numerus und steht in der Regel <b>hinter</b> dem Nomen. Beides ist neu: Deutsch stellt es davor und dekliniert es nach Kasus und Artikelart. Italienisch kennt keine schwache und starke Deklination — es gibt nur vier Formen, und die Stellung ist meistens nachgestellt.</p><div class='table-wrap'><table class='gt'><thead><tr><th>Typ</th><th>m. Sg.</th><th>f. Sg.</th><th>m. Pl.</th><th>f. Pl.</th></tr></thead><tbody><tr><td>4 Endungen</td><td class='it'>rosso</td><td>rossa</td><td>rossi</td><td>rosse</td></tr><tr><td>2 Endungen</td><td class='it'>verde</td><td>verde</td><td>verdi</td><td>verdi</td></tr><tr><td>unveränderlich</td><td class='it'>blu</td><td>blu</td><td>blu</td><td>blu</td></tr></tbody></table></div><p>Unveränderlich sind <em>blu, rosa, viola, beige, marrone</em> (letzteres wird gesprochen doch flektiert) und Lehnwörter: <em>chic, snob, super</em>.</p><p>Bei gemischter Gruppe gewinnt das Maskulinum: <em>Marco e Anna sono italiani</em>.</p>"
  },
  "ref:g-agg-posizione": {
    title: "Wo das Adjektiv steht",
    sub: "vor dem Nomen oder dahinter",
    body: "<p>Standard ist die Nachstellung — der Punkt, an dem das deutsche Sprachgefühl am zuverlässigsten in die Irre führt. <em>Una casa grande</em>, nicht „una grande casa\", wenn das Haus wirklich groß ist.</p><p>Eine Handvoll häufiger, nicht unterscheidender Adjektive geht voran: <em>bello, buono, grande, piccolo, giovane, vecchio, nuovo, bravo</em>. Verschiebt man sie, ändert sich die Bedeutung:</p><div class='table-wrap'><table class='gt'><thead><tr><th>davor</th><th>dahinter</th></tr></thead><tbody><tr><td class='it'>un vecchio amico (ein alter Freund, langjährig)</td><td>un amico vecchio (ein betagter Freund)</td></tr><tr><td class='it'>un grande uomo (ein großer Mann, bedeutend)</td><td>un uomo grande (ein großer Mann, körperlich)</td></tr><tr><td class='it'>un buon medico (fachlich gut)</td><td>un medico buono (ein guter Mensch)</td></tr><tr><td class='it'>una certa informazione (eine gewisse Information)</td><td>un'informazione certa (eine gesicherte)</td></tr><tr><td class='it'>un alto magistrato (hochrangig)</td><td>un magistrato alto (körperlich groß)</td></tr></tbody></table></div><p>Die Paare entsprechen genau dem deutschen „ein großer Mann\" in seinen zwei Lesarten — nur dass Italienisch sie durch die Stellung auseinanderhält, wo Deutsch auf den Kontext angewiesen ist.</p><p><b>Bello</b> und <b>quello</b> vor einem Nomen verhalten sich wie der Artikel: <em>bel libro, bello studente, begli amici, bella casa</em>.</p>"
  },
  "ref:g-agg-gradi": {
    title: "Komparativ und Superlativ",
    sub: "comparativo und superlativo",
    body: "<h4>Komparativ</h4><ul><li>mehr: <em>Anna è <b>più</b> alta <b>di</b> Marco</em>. Italienisch bildet den Komparativ analytisch mit <em>più</em>, Deutsch synthetisch mit <em>-er</em>. Ein „*altera\" gibt es nicht.</li><li>vor einem Verb, Adjektiv oder einer Präposition steht <b>che</b>: <em>è più facile parlare che scrivere</em></li><li>weniger: <em><b>meno</b> caro <b>di</b>…</em></li><li>gleich: <em>tanto… quanto</em>, <em>così… come</em></li></ul><h4>Superlativ</h4><ul><li>relativ: <em>il <b>più</b> bello <b>della</b> città</em></li><li>absolut: <em>bell<b>issimo</b></em>, oder <em>molto bello</em>. Deutsch braucht „sehr\" oder „äußerst\"; Italienisch hat dafür eine Endung.</li></ul><h4>Unregelmäßige Formen</h4><div class='table-wrap'><table class='gt'><thead><tr><th>Grundform</th><th>Komparativ</th><th>Superlativ</th></tr></thead><tbody><tr><td>buono</td><td class='it'>migliore</td><td>ottimo / il migliore</td></tr><tr><td>cattivo</td><td class='it'>peggiore</td><td>pessimo / il peggiore</td></tr><tr><td>grande</td><td class='it'>maggiore</td><td>massimo</td></tr><tr><td>piccolo</td><td class='it'>minore</td><td>minimo</td></tr></tbody></table></div><p>Dieselben Paare wie „gut → besser\" und „schlecht → schlimmer\": auch Deutsch bildet gerade bei den häufigsten Adjektiven unregelmäßig. In <b>C1</b> kommen umgangssprachliche Verstärker (<em>magra magra</em>), Präfixe (<em>arcicontento, straricco, iperattivo</em>), feste Wendungen (<em>stanco morto, ubriaco fradicio, buono come il pane</em>) und die <em>-errimo</em>-Formen (<em>acerrimo, celeberrimo</em>) dazu.</p>"
  },
  "ref:g-possessivi": {
    title: "Die Possessiva",
    sub: "mio, tuo, suo… und die Familienfalle",
    body: "<p>Das Possessivum richtet sich nach dem <b>Besitzstück</b>, nicht nach dem Besitzer.</p><p class='callout callout--trap'>Das ist ein echter Informationsverlust gegenüber dem Deutschen. „Seine Schwester\" und „ihre Schwester\" sind beide <em>sua sorella</em>: das Genus des Besitzers wird schlicht nicht ausgedrückt. Wo Deutsch sein/ihr unterscheidet, muss Italienisch den Kontext sprechen lassen — oder <em>di lui / di lei</em> anhängen.</p><div class='table-wrap'><table class='gt'><thead><tr><th>Person</th><th>m. Sg.</th><th>f. Sg.</th><th>m. Pl.</th><th>f. Pl.</th></tr></thead><tbody><tr><td>io</td><td class='it'>mio</td><td>mia</td><td>miei</td><td>mie</td></tr><tr><td>tu</td><td class='it'>tuo</td><td>tua</td><td>tuoi</td><td>tue</td></tr><tr><td>lui/lei</td><td class='it'>suo</td><td>sua</td><td>suoi</td><td>sue</td></tr><tr><td>noi</td><td class='it'>nostro</td><td>nostra</td><td>nostri</td><td>nostre</td></tr><tr><td>voi</td><td class='it'>vostro</td><td>vostra</td><td>vostri</td><td>vostre</td></tr><tr><td>loro</td><td class='it'>loro</td><td>loro</td><td>loro</td><td>loro</td></tr></tbody></table></div><p>Normalerweise steht der Artikel dabei: <em>il mio libro</em>, wo Deutsch nur „mein Buch\" sagt. <b>Kein Artikel</b> bei einem einzelnen, nicht näher bestimmten Familienmitglied: <em>mia madre, tuo fratello</em>. Er kehrt zurück im Plural (<em>i miei genitori</em>), beim Diminutiv (<em>la mia sorellina</em>), bei näherer Bestimmung (<em>la mia sorella maggiore</em>) und bei <em>loro</em> (<em>la loro madre</em>).</p>"
  },
  "ref:g-pron-soggetto": {
    title: "Die Subjektpronomen",
    sub: "io, tu, lui… und warum sie wegfallen",
    body: "<p><em>io, tu, lui/lei, noi, voi, loro</em>. Sie fallen meistens weg, weil die Endung schon sagt, wer handelt.</p><p class='callout callout--trap'>Deutsch verlangt das Subjekt in jedem Satz, auch das leere „es\" („es regnet\"). Italienisch sagt <em>piove</em> — ohne alles. Wer das Pronomen ohne Grund setzt, klingt betont bis vorwurfsvoll: <em>io lavoro</em> heißt „ICH arbeite (und du nicht)\".</p><p>Gebraucht werden sie für den <b>Kontrast</b> (<em>io lavoro, tu dormi</em>), nach <em>anche</em>, <em>neanche</em>, <em>nemmeno</em>, und in Kurzantworten (<em>Chi è? — Io.</em>).</p><p><b>Lei</b> mit großem L ist die Höflichkeitsform, für Männer und Frauen gleichermaßen, mit dem Verb in der <b>dritten Person Singular</b>. Das ist der Unterschied zum deutschen „Sie\", das im Plural steht: man spricht die Person an, als spräche man über sie. Im Plural ist heute <em>voi</em> üblich; <em>Loro</em> lebt nur noch in sehr formellem Register.</p><p>Die Formen <em>egli, ella, esso, essi</em> gehören der Schriftsprache an.</p>"
  },
  "ref:g-pron-diretti": {
    title: "Die Akkusativpronomen",
    sub: "mi, ti, lo, la, ci, vi, li, le",
    body: "<p>Sie ersetzen das Objekt ohne Präposition — also genau das, was im Deutschen im <b>Akkusativ</b> steht. Die Kasusfrage „wen oder was?\" führt dich hier zuverlässig zur richtigen Form.</p><p>Sie stehen <b>vor</b> dem konjugierten Verb: <em>lo vedo</em> für „ich sehe ihn\".</p><div class='table-wrap'><table class='gt'><thead><tr><th>Bedeutung</th><th>unbetont</th><th>betont</th></tr></thead><tbody><tr><td>mich</td><td class='it'>mi</td><td>me</td></tr><tr><td>dich</td><td class='it'>ti</td><td>te</td></tr><tr><td>ihn</td><td class='it'>lo</td><td>lui</td></tr><tr><td>sie (Sg.)</td><td class='it'>la</td><td>lei</td></tr><tr><td>uns</td><td class='it'>ci</td><td>noi</td></tr><tr><td>euch</td><td class='it'>vi</td><td>voi</td></tr><tr><td>sie (m, Pl.)</td><td class='it'>li</td><td>loro</td></tr><tr><td>sie (f, Pl.)</td><td class='it'>le</td><td>loro</td></tr></tbody></table></div><p><b>Partizipangleichung.</b> In zusammengesetzten Zeiten mit <em>avere</em> richtet sich das Partizip nach einem vorangehenden Akkusativpronomen: <em>L'ho vista</em>, <em>Li ho comprati</em>, <em>Le ho salutate</em>. Deutsch kennt so etwas überhaupt nicht — das Partizip bleibt dort immer gleich.</p><p>Mit Infinitiv nach einem Modalverb sind zwei Stellungen möglich: <em>ti posso aiutare</em> = <em>posso aiutarti</em>.</p>"
  },
  "ref:g-pron-indiretti": {
    title: "Die Dativpronomen",
    sub: "mi, ti, gli, le, ci, vi, gli",
    body: "<p>Sie antworten auf „wem?\" und ersetzen <em>a + Person</em> — der italienische Ausdruck für das, was Deutsch im <b>Dativ</b> ausdrückt: <em>Telefono a Marco → Gli telefono</em>.</p><p>Formen: <em>mi, ti, <b>gli</b> (ihm), <b>le</b> (ihr), ci, vi, <b>gli</b> (ihnen)</em>. Im formellen Register heißt „ihnen\" <em>loro</em> und steht hinter dem Verb: <em>Telefono loro</em>.</p><p>Die Akkusativ/Dativ-Unterscheidung, die du aus dem Deutschen mitbringst, ist hier der Schlüssel: <em>lo</em> für den Akkusativ, <em>gli</em> für den Dativ. Wer diesen Unterschied schon fühlt, hat den schwierigsten Teil hinter sich.</p><p class='callout callout--trap'><b>Gli</b> ist zugleich Artikel („gli amici\") und Pronomen („gli parlo\"). Die Stellung im Satz trennt beide.</p><p>Das Partizip richtet sich <b>nicht</b> nach einem Dativpronomen: <em>Le ho parlato</em>, nie „parlata\".</p><p>Verben, die im Italienischen den Dativ verlangen: <em>telefonare a, rispondere a, chiedere a, credere a, piacere a, dispiacere a</em>. Die Überschneidung mit dem deutschen Dativ ist groß, aber nicht vollständig: <em>chiedere a qualcuno</em> steht gegen „jemanden fragen\" im Akkusativ.</p>"
  },
  "ref:g-pron-combinati": {
    title: "Kombinierte Pronomen",
    sub: "me lo, te la, glielo, ce ne…",
    body: "<p>Treffen zwei Pronomen aufeinander, steht das indirekte zuerst und sein <em>-i</em> wird zu <em>-e</em>. Deutsch macht es umgekehrt: „ich gebe es ihm\" setzt den Akkusativ voran, sobald er ein Pronomen ist. Diese Reihenfolge muss man bewusst umdrehen.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>lo</th><th>la</th><th>li</th><th>le</th><th>ne</th></tr></thead><tbody><tr><td>mi</td><td class='it'>me lo</td><td>me la</td><td>me li</td><td>me le</td><td>me ne</td></tr><tr><td>ti</td><td class='it'>te lo</td><td>te la</td><td>te li</td><td>te le</td><td>te ne</td></tr><tr><td>gli / le</td><td class='it'>glielo</td><td>gliela</td><td>glieli</td><td>gliele</td><td>gliene</td></tr><tr><td>ci</td><td class='it'>ce lo</td><td>ce la</td><td>ce li</td><td>ce le</td><td>ce ne</td></tr><tr><td>vi</td><td class='it'>ve lo</td><td>ve la</td><td>ve li</td><td>ve le</td><td>ve ne</td></tr></tbody></table></div><p><b>Glielo</b> deckt „ihm\", „ihr\" und „ihnen\" auf einmal ab und wird zusammengeschrieben. <em>Do il libro a Maria → Glielo do.</em></p>"
  },
  "ref:g-ci-ne": {
    title: "Ci und ne",
    sub: "zwei Partikeln, die die halbe Sprache tragen",
    body: "<p>Gute Nachricht: du hast sie schon, nämlich als <b>da-Formen</b>. <em>Ci penso</em> ist „ich denke daran\", <em>ne parliamo</em> ist „wir sprechen davon\", <em>ne voglio tre</em> ist „ich will drei davon\". Wo Englisch und Spanisch nichts anzubieten haben, liefert Deutsch eine fast lückenlose Entsprechung.</p><h4>CI</h4><ul><li>Ort: <em>Vai a Roma? — Sì, ci vado domani.</em> (dorthin)</li><li>ersetzt <em>a + Sache</em>: <em>Pensi all'esame? — Ci penso sempre.</em> (daran)</li><li>in <em>c'è / ci sono</em> — das „es gibt\"</li><li>in pronominalen Verben: <em>farcela</em> (es schaffen), <em>volerci</em> (nötig sein), <em>metterci</em> (Zeit brauchen), <em>entrarci</em> (damit zu tun haben)</li></ul><h4>NE</h4><ul><li>Teil einer Menge: <em>Quante mele vuoi? — Ne voglio tre.</em> (davon)</li><li>ersetzt <em>di + Sache/Person</em>: <em>Parliamo del film? — Ne parliamo domani.</em> (darüber)</li><li>Herkunft: <em>Vieni dal lavoro? — Sì, ne vengo adesso.</em> (von dort)</li><li>in Verben: <em>andarsene</em> (weggehen), <em>fregarsene</em> (sich nicht scheren), <em>accorgersene</em></li></ul><p>Mit <em>ne</em> gleicht sich das Partizip im Numerus an: <em>Ne ho comprate tre.</em> Das hat keine deutsche Entsprechung.</p>"
  },
  "ref:g-relativi": {
    title: "Die Relativpronomen",
    sub: "che, cui, il quale, chi",
    body: "<ul><li><b>che</b> — unveränderlich, als Subjekt und als Akkusativobjekt: <em>il libro che leggo</em>. Ein einziges Wort für alles, wo Deutsch der/die/das nach Genus, Numerus und Kasus durchdekliniert. Eine erhebliche Erleichterung.</li><li><b>cui</b> — nach einer Präposition: <em>la persona <b>a cui</b> penso</em>, <em>la città <b>in cui</b> vivo</em>. Die Präposition steht vorn, nie am Ende.</li><li>mit Artikel drückt <em>cui</em> Besitz aus: <em>il ragazzo <b>la cui</b> madre è medico</em> — das deutsche „dessen/deren\", aber der Artikel richtet sich nach dem Besitzstück, nicht nach dem Besitzer.</li><li><b>il quale / la quale / i quali / le quali</b> — formelle Variante, nützlich gegen Mehrdeutigkeit, wie „welcher\".</li><li><b>chi</b> — „wer\" im Sinne von „derjenige, der\", nur für Personen, immer Singular: <em>Chi dorme non piglia pesci.</em></li></ul><p class='callout callout--trap'>Der Relativsatz ändert die Wortstellung <b>nicht</b>: das Verb bleibt an zweiter Stelle, es wandert nicht ans Ende. <em>Il libro che ho letto ieri</em>, nicht „*che ieri gelesen habe\". Das ist der hartnäckigste deutsche Reflex im ganzen Kurs.</p><p>In <b>C1</b> kommt das neutrale Relativum dazu: <em><b>il che</b> mi sembra strano</em> („was mir seltsam vorkommt\"), <em>la ragione <b>per cui</b>…</em></p>"
  },
  "ref:g-si": {
    title: "Alle Werte von SI",
    sub: "reflexiv, reziprok, unpersönlich, passivisch",
    body: "<p>Ein Teilchen für das, was Deutsch auf „sich\" und „man\" verteilt.</p><div class='table-wrap'><table class='gt'><thead><tr><th>Wert</th><th>Beispiel</th><th>Hinweis</th></tr></thead><tbody><tr><td>reflexiv</td><td class='it'>Marco si lava.</td><td>er wäscht sich</td></tr><tr><td>reziprok</td><td class='it'>Si salutano ogni giorno.</td><td>einander</td></tr><tr><td>unpersönlich</td><td class='it'>In Italia si mangia bene.</td><td>„man isst gut\"</td></tr><tr><td>passivisch (passivante)</td><td class='it'>Qui si vendono panini.</td><td>„hier werden Brötchen verkauft\"</td></tr><tr><td>Anleitung</td><td class='it'>Il volante si tiene così.</td><td>so macht man das</td></tr><tr><td>toskanisches „wir\"</td><td class='it'>Stasera noi si va al cinema.</td><td>regional</td></tr></tbody></table></div><p class='callout callout--trap'>Der Unterschied zum deutschen „man\": beim passivischen <em>si</em> richtet sich das Verb nach der <b>Sache</b>, nicht nach dem gedachten Handelnden. <em>Si vendono panini</em> steht im Plural, „man verkauft Brötchen\" im Singular.</p><p>Unpersönliches <em>si</em> mit einem reflexiven Verb ergibt <b>ci si</b>: <em>ci si alza presto</em>. In zusammengesetzten Zeiten nimmt unpersönliches <em>si</em> immer <em>essere</em>, und das Partizip endet auf <em>-i</em>: <em>si è mangiato bene</em>, aber <em>si è stati contenti</em>.</p>"
  },
  "ref:g-verbi-pronominali": {
    title: "Pronominale Verben",
    sub: "farcela, cavarsela, prendersela",
    body: "<p>Eine Familie von Verben, deren Bedeutung sich aus den Teilen nicht erschließt. Das deutsche Gegenstück sind die trennbaren Verben und die festen Wendungen mit „es\": „es schaffen\", „es sich gutgehen lassen\", „es auf jemanden abgesehen haben\". Dasselbe Prinzip, andere Bausteine.</p><div class='table-wrap'><table class='gt'><thead><tr><th>Form</th><th>Bedeutung</th><th>Beispiel</th></tr></thead><tbody><tr><td class='it'>farcela</td><td>es schaffen</td><td>Non ce la faccio più.</td></tr><tr><td class='it'>cavarsela</td><td>zurechtkommen</td><td>Me la cavo con l'italiano.</td></tr><tr><td class='it'>prendersela</td><td>beleidigt sein</td><td>Non te la prendere.</td></tr><tr><td class='it'>andarsene</td><td>weggehen</td><td>Me ne vado.</td></tr><tr><td class='it'>fregarsene</td><td>sich nicht scheren</td><td>Se ne frega di tutto.</td></tr><tr><td class='it'>volerci</td><td>nötig sein, dauern</td><td>Ci vogliono due ore.</td></tr><tr><td class='it'>metterci</td><td>Zeit brauchen</td><td>Ci metto un'ora.</td></tr><tr><td class='it'>avercela con</td><td>es auf jemanden abgesehen haben</td><td>Ce l'ha con me.</td></tr></tbody></table></div><p>In zusammengesetzten Zeiten nehmen sie <em>essere</em>, und das Partizip richtet sich nach <em>la</em>: <em>me la sono cavata</em>, <em>ce l'ho fatta</em>.</p>"
  },
  "ref:g-presente": {
    title: "Das Präsens",
    sub: "drei Konjugationen und das -isc--Muster",
    body: "<div class='table-wrap'><table class='gt'><thead><tr><th>Person</th><th>-are</th><th>-ere</th><th>-ire</th><th>-ire (-isc-)</th></tr></thead><tbody><tr><td>io</td><td class='it'>parlo</td><td>leggo</td><td>dormo</td><td>capisco</td></tr><tr><td>tu</td><td class='it'>parli</td><td>leggi</td><td>dormi</td><td>capisci</td></tr><tr><td>lui/lei</td><td class='it'>parla</td><td>legge</td><td>dorme</td><td>capisce</td></tr><tr><td>noi</td><td class='it'>parliamo</td><td>leggiamo</td><td>dormiamo</td><td>capiamo</td></tr><tr><td>voi</td><td class='it'>parlate</td><td>leggete</td><td>dormite</td><td>capite</td></tr><tr><td>loro</td><td class='it'>parlano</td><td>leggono</td><td>dormono</td><td>capiscono</td></tr></tbody></table></div><h4>Was es abdeckt</h4><p>Wie im Deutschen deckt ein Präsens mehreres ab: den Augenblick, die Gewohnheit, die nahe Zukunft mit Zeitangabe (<em>domani parto</em>, „morgen fahre ich\"), allgemeine Wahrheiten, das historische Präsens. Der Gebrauch entspricht dem deutschen fast eins zu eins.</p><p>Neu ist die Gruppe <b>-isc-</b>: einige <em>-ire</em>-Verben schieben <em>-isc-</em> in die ersten drei Personen und in die dritte Plural ein (<em>capisco, capisci, capisce, capiamo, capite, capiscono</em>). Welche Verben dazugehören, muss man lernen.</p><p>Rechtschreibänderungen: <em>-care/-gare</em> setzen ein h (<em>cerchi, paghi</em>), <em>-ciare/-giare/-iare</em> verlieren das i (<em>mangi, studi</em>).</p>"
  },
  "ref:g-passato-prossimo": {
    title: "Passato prossimo",
    sub: "avere oder essere, das Partizip, die Angleichung",
    body: "<p>Die Vergangenheit des Alltagsgesprächs: <b>avere oder essere im Präsens + Partizip</b>. Das ist das deutsche Perfekt, Bauteil für Bauteil.</p><h4>Regelmäßige Partizipien</h4><p><em>-are → -ato</em> (parlato), <em>-ere → -uto</em> (creduto), <em>-ire → -ito</em> (finito).</p><h4>Die Wahl des Hilfsverbs</h4><p>Hier zahlt sich Deutsch aus: auch du teilst zwischen „haben\" und „sein\", und zwar nach fast demselben Kriterium. Bewegung und Zustandswechsel nehmen <em>essere</em>, genau wie „ich bin gegangen\", „ich bin geblieben\", „ich bin geworden\".</p><ul><li><b>avere</b>: transitive Verben mit direktem Objekt — <em>ho mangiato la pizza</em></li><li><b>essere</b>: Bewegung und Zustandswechsel (<em>andare, venire, arrivare, partire, uscire, entrare, salire, scendere, tornare, nascere, morire, diventare, restare, rimanere, stare, essere, piacere, succedere, costare</em>) und alle reflexiven Verben</li></ul><p class='callout callout--trap'>Zwei Abweichungen: alle reflexiven Verben nehmen <em>essere</em> (<em>mi sono lavato</em>), während Deutsch „ich habe mich gewaschen\" sagt. Und <em>essere</em> selbst nimmt <em>essere</em>: <em>sono stato</em>, „ich bin gewesen\" — hier stimmt es wieder überein.</p><p>Mit <em>essere</em> richtet sich das Partizip nach dem Subjekt: <em>sono andato / sono andata / siamo andati / sono andate</em>. Deutsch gleicht das Partizip nie an; das ist neu und muss mitgesprochen werden.</p><h4>Häufige unregelmäßige Partizipien</h4><p><em>fare→fatto, dire→detto, vedere→visto, prendere→preso, mettere→messo, leggere→letto, scrivere→scritto, aprire→aperto, chiudere→chiuso, chiedere→chiesto, rispondere→risposto, essere→stato, nascere→nato, morire→morto, venire→venuto, rimanere→rimasto, vivere→vissuto, perdere→perso, offrire→offerto, scegliere→scelto, decidere→deciso, vincere→vinto, bere→bevuto</em>.</p>"
  },
  "ref:g-imperfetto": {
    title: "Imperfetto",
    sub: "Beschreibung, Gewohnheit, Hintergrund",
    body: "<p>Praktisch bei allen Verben regelmäßig: Stamm + <em>-vo, -vi, -va, -vamo, -vate, -vano</em>. Ausnahmen: <em>essere</em> (ero, eri, era…), <em>fare</em> (facevo), <em>dire</em> (dicevo), <em>bere</em> (bevevo).</p><p class='callout callout--trap'>Das deutsche Präteritum ist <b>keine</b> Entsprechung. „Ich ging\" und „ich bin gegangen\" unterscheiden sich im Deutschen nach Register (Schrift gegen Gespräch), im Italienischen nach <b>Aspekt</b>: das Imperfetto malt den Hintergrund, das Passato prossimo meldet das Ereignis. Wer nach dem deutschen Gefühl wählt, wählt falsch.</p><div class='table-wrap'><table class='gt'><thead><tr><th>imperfetto</th><th>passato prossimo</th></tr></thead><tbody><tr><td class='it'>Beschreibung, Hintergrund</td><td>Ereignis, ein Punkt</td></tr><tr><td class='it'>Pioveva e faceva freddo.</td><td>Ha smesso di piovere alle sei.</td></tr><tr><td class='it'>wiederholt: da bambino andavo</td><td>abgeschlossen: ieri sono andato</td></tr><tr><td class='it'>Dauer ohne Grenzen</td><td>Dauer mit Grenzen: ho lavorato per tre ore</td></tr></tbody></table></div><p>Weitere Verwendungen (B1): die höfliche Bitte (<em>volevo un caffè</em>, wie „ich wollte einen Kaffee\"), das Erzählen eines Traums, der Zeitungsstil und die irreale Bedingung in der Umgangssprache (<em>se lo sapevo, venivo</em>).</p>"
  },
  "ref:g-futuro": {
    title: "Futuro semplice und anteriore",
    sub: "Pläne, Vermutungen, Vorzeitigkeit",
    body: "<p>Infinitivstamm ohne das End-<em>e</em> (bei -are wird a zu e) + <em>-ò, -ai, -à, -emo, -ete, -anno</em>: <em>parlerò, prenderò, partirò</em>. Es ist eine Endung, kein Hilfsverb — kein „werden\".</p><p>Unregelmäßige Stämme: <em>essere→sar-, avere→avr-, andare→andr-, venire→verr-, volere→vorr-, potere→potr-, dovere→dovr-, sapere→sapr-, vedere→vedr-, bere→berr-, rimanere→rimarr-, tenere→terr-</em>.</p><h4>Was es leistet</h4><ul><li>die Zukunft: <em>l'anno prossimo andrò in Italia</em></li><li><b>eine Vermutung über die Gegenwart</b>: <em>Che ore sono? — Saranno le tre.</em> Deutsch macht dasselbe mit „wird\": „es wird drei Uhr sein\". Diese Verwendung überträgt sich direkt.</li><li>Einräumung: <em>Sarà anche bravo, ma non mi piace.</em></li></ul><p>Wie im Deutschen wird im Gespräch oft das Präsens statt des Futurs verwendet, sobald eine Zeitangabe dabeisteht: <em>domani parto</em>, „morgen fahre ich\".</p><p><b>Futuro anteriore</b> (avrò fatto / sarò andato) markiert eine vor einer anderen zukünftigen Handlung abgeschlossene Handlung: <em>Quando avrò finito, ti chiamo</em>, und die Vermutung über Vergangenes: <em>Avrà perso il treno.</em> („er wird den Zug verpasst haben\")</p>"
  },
  "ref:g-trapassato": {
    title: "Trapassato prossimo",
    sub: "die Vergangenheit vor der Vergangenheit",
    body: "<p>Imperfetto von <em>avere/essere</em> + Partizip: <em>avevo mangiato, ero andato</em>. Das ist das deutsche Plusquamperfekt, mit derselben Funktion und derselben Bauweise.</p><p>Es markiert eine Handlung, die vor einer anderen vergangenen liegt: <em>Quando sono arrivato, il treno <b>era già partito</b>.</em></p><p>Die Umgangssprache ersetzt es oft durch das Passato prossimo, in der geschriebenen Erzählung ist es unverzichtbar: es hält die Chronologie zusammen.</p>"
  },
  "ref:g-passato-remoto": {
    title: "Passato remoto",
    sub: "Erzählung, Geschichte, Süditalien",
    body: "<p>Regelmäßig: <em>-are</em>: ai, asti, ò, ammo, aste, arono; <em>-ere</em>: ei/etti, esti, é/ette, emmo, este, erono/ettero; <em>-ire</em>: ii, isti, ì, immo, iste, irono.</p><p>Sehr viele -ere-Verben folgen dem <b>1-3-3-Muster</b>: nur io, lui/lei und loro sind unregelmäßig, der Rest ist regelmäßig. <em>prendere → presi, prendesti, prese, prendemmo, prendeste, presero</em>.</p><h4>Wann es gebraucht wird</h4><ul><li>in literarischer und historischer Erzählung: <em>Dante nacque nel 1265</em></li><li>für weit zurückliegende, abgeschlossene Ereignisse ohne Gegenwartsbezug</li><li>in der Alltagssprache des Südens, auch für gestern; im Norden gibt es das kaum</li></ul><p class='callout callout--trap'>Die Versuchung ist groß, das Passato remoto mit dem Präteritum gleichzusetzen, weil beide „literarisch\" wirken. Der Schnitt verläuft aber anders: Deutsch trennt Schrift von Gespräch, Italienisch trennt fern von nah — und obendrein Nord von Süd. In Neapel hört man es am Kaffeetresen, in Mailand nie.</p><p><b>Trapassato remoto</b> (<em>ebbi fatto</em>) erscheint nur nach Temporalkonjunktionen in literarischen Texten: <em>Appena ebbe finito, uscì.</em></p>"
  },
  "ref:g-condizionale": {
    title: "Der Konditional",
    sub: "vorrei, potrei, avrei voluto",
    body: "<p>Derselbe Stamm wie beim Futur + <em>-ei, -esti, -ebbe, -emmo, -este, -ebbero</em>: <em>parlerei, sarei, avrei, vorrei, potrei</em>. Es ist eine Endung, nicht „würde\" + Infinitiv: <em>verrei</em> heißt „ich würde kommen\" in einem Wort.</p><h4>Was er leistet</h4><ul><li>die höfliche Bitte: <em>Vorrei un caffè.</em> — mit Abstand der häufigste Gebrauch, das „ich hätte gern\" bzw. „ich möchte\"</li><li>Rat: <em>Dovresti riposare.</em> („du solltest dich ausruhen\")</li><li>Wunsch: <em>Mi piacerebbe vederti.</em></li><li>unbestätigte Information in der Presse: <em>Il ministro sarebbe pronto a dimettersi.</em> Deutsch benutzt dafür den Konjunktiv I („der Minister sei bereit\"), Italienisch den Konditional. Die Funktion ist dieselbe, die Form nicht.</li></ul><p><b>Condizionale passato</b> (<em>avrei fatto, sarei andato</em>) deckt die nicht eingetretene Möglichkeit ab (<em>sarei venuto, ma…</em>) und <b>die Zukunft aus der Vergangenheit gesehen</b>: <em>Ha detto che <b>sarebbe venuto</b></em> — „er sagte, er würde kommen\". Deutsch nimmt hier „würde\" + Infinitiv, Italienisch den <b>zusammengesetzten</b> Konditional.</p>"
  },
  "ref:g-congiuntivo-pres": {
    title: "Congiuntivo presente und passato",
    sub: "wann er verlangt wird und wann nicht",
    body: "<p>Endungen: <em>-are</em> → i, i, i, iamo, iate, ino; <em>-ere/-ire</em> → a, a, a, iamo, iate, ano; <em>-isc-</em> → isca, isca, isca, iamo, iate, iscano.</p><p>Du hast einen Konjunktiv, aber er arbeitet woanders. Der deutsche Konjunktiv I gehört der indirekten Rede, der Konjunktiv II dem Irrealen. Der italienische Congiuntivo steht nach <b>Meinung, Wille und Gefühl</b> — ein Feld, auf dem Deutsch schlicht den Indikativ nimmt: „ich glaube, dass er recht hat\".</p><p>Die ersten drei Personen sind identisch, deshalb wird beim Congiuntivo <b>das Pronomen nicht weggelassen</b>: <em>penso che <b>tu</b> abbia ragione</em>.</p><h4>Verlangt den Congiuntivo</h4><ul><li>Meinung und Vermutung: <em>penso che, credo che, mi sembra che, immagino che</em></li><li>Wille und Gefühl: <em>voglio che, spero che, temo che, mi dispiace che, sono contento che</em></li><li>unpersönliche Ausdrücke: <em>è necessario che, bisogna che, è possibile che, è strano che</em></li><li>Konjunktionen: <em>benché, sebbene, nonostante, affinché, perché (=damit), purché, a meno che, prima che, senza che, come se</em></li><li>verneinte oder unbestimmte Relativsätze: <em>cerco una persona che parli inglese</em></li></ul><p class='callout callout--trap'>Der teuerste Unterschied: <em>penso che</em>, <em>credo che</em> und <em>spero che</em> verlangen den Congiuntivo, während „ich denke, dass\", „ich glaube, dass\" und „ich hoffe, dass\" im Deutschen den Indikativ nehmen. Das sind die drei häufigsten Verben der Liste, und genau dort greift der deutsche Reflex daneben.</p><h4>Verlangt ihn nicht</h4><p>Gewissheit: <em>so che, è certo che, è vero che, siccome, perché (=weil)</em>. Bei gleichem Subjekt in beiden Sätzen steht <em>di</em> + Infinitiv: <em>penso <b>di</b> avere ragione</em> — „ich glaube recht zu haben\".</p><p><b>Congiuntivo passato</b>: <em>abbia fatto / sia andato</em> — eine Handlung vor einer Hauptsatzhandlung im Präsens.</p>"
  },
  "ref:g-congiuntivo-imp": {
    title: "Congiuntivo imperfetto und trapassato",
    sub: "Zeitenfolge und Wünsche",
    body: "<p>Imperfetto: Stamm + <em>-ssi, -ssi, -sse, -ssimo, -ste, -ssero</em> (<em>parlassi, prendessi, dormissi</em>). Unregelmäßig: <em>essere → fossi</em>, <em>fare → facessi</em>, <em>dare → dessi</em>, <em>stare → stessi</em>, <em>bere → bevessi</em>, <em>dire → dicessi</em>.</p><p>Funktional liegt das nahe am deutschen Konjunktiv II: <em>fossi</em> ist „wäre\", <em>avessi</em> ist „hätte\", <em>venisse</em> ist „käme\". Und wie im Deutschen ist er im Irrealen unverzichtbar.</p><h4>Zeitenfolge</h4><div class='table-wrap'><table class='gt'><thead><tr><th>Hauptsatz</th><th>gleichzeitig</th><th>vorzeitig</th></tr></thead><tbody><tr><td>Präsens</td><td class='it'>congiuntivo presente</td><td>congiuntivo passato</td></tr><tr><td>Vergangenheit</td><td class='it'>congiuntivo imperfetto</td><td>congiuntivo trapassato</td></tr></tbody></table></div><p><em>Penso che <b>sia</b> partito</em> → <em>Pensavo che <b>fosse</b> partito.</em> Diese Rückstufung ist im Italienischen Pflicht; Deutsch kennt sie so nicht und lässt die Zeitform des Nebensatzes meist stehen.</p><h4>Der Wunschkonjunktiv</h4><p>Allein, ohne Hauptsatz: <em>Piovesse almeno!</em>, <em>Magari venisse!</em>, <em>Non l'avessi mai detto!</em>, <em>Volesse il cielo!</em> — das deutsche „Käme er doch!\" oder „Hätte ich das nie gesagt!\", mit derselben Wirkung.</p><p>In <b>C1</b> kommen der vorangestellte Nebensatz (<em>Che gli italiani fossero un popolo creativo, lo sapevano tutti</em>) und Nomen der Meinung und des Gefühls dazu (<em>il dubbio che, la speranza che, l'ipotesi che</em>).</p>"
  },
  "ref:g-periodo-ipotetico": {
    title: "Die Bedingungssätze",
    sub: "drei Typen mit se",
    body: "<div class='table-wrap'><table class='gt'><thead><tr><th>Typ</th><th>se-Satz</th><th>Hauptsatz</th></tr></thead><tbody><tr><td>1. real</td><td class='it'>se + Indikativ</td><td>Indikativ / Imperativ</td></tr><tr><td>2. möglich</td><td class='it'>se + cong. imperfetto</td><td>Konditional I</td></tr><tr><td>3. irreal</td><td class='it'>se + cong. trapassato</td><td>Konditional II</td></tr></tbody></table></div><ul><li><em>Se piove, resto a casa.</em></li><li><em>Se avessi tempo, verrei con te.</em></li><li><em>Se avessi studiato, avrei passato l'esame.</em></li></ul><p>Der Bau entspricht dem deutschen genau: „wenn ich Zeit hätte, käme ich\" und „wenn ich gelernt hätte, hätte ich bestanden\". Auch bei dir steht im wenn-Satz der Konjunktiv II, nicht der Indikativ — dieses Kapitel schenkt dir das Deutsche fast vollständig.</p><p class='callout callout--trap'>Nach <b>se</b> steht nie ein Konditional oder ein Futur. „Se avrei\" ist ein Fehler, den Italiener sofort hören — genau wie „wenn ich würde haben\" im Deutschen. Der Reflex ist also schon vorhanden.</p><p>Mischtypen sind häufig: <em>Se avessi studiato, adesso lavorerei qui.</em> Umgangssprachlich hört man das doppelte Imperfetto: <em>Se lo sapevo, non venivo</em> — im Gespräch in Ordnung, im Geschriebenen nicht.</p>"
  },
  "ref:g-imperativo": {
    title: "Der Imperativ",
    sub: "tu, Lei, noi, voi und die Verneinung",
    body: "<div class='table-wrap'><table class='gt'><thead><tr><th>Person</th><th>-are</th><th>-ere</th><th>-ire</th></tr></thead><tbody><tr><td>tu</td><td class='it'>parla</td><td>prendi</td><td>senti</td></tr><tr><td>Lei</td><td class='it'>parli</td><td>prenda</td><td>senta</td></tr><tr><td>noi</td><td class='it'>parliamo</td><td>prendiamo</td><td>sentiamo</td></tr><tr><td>voi</td><td class='it'>parlate</td><td>prendete</td><td>sentite</td></tr></tbody></table></div><p class='callout callout--trap'><b>Die verneinte du-Form nimmt den Infinitiv</b>: <em>non parlare!</em>, <em>non andare!</em>. Deutsch sagt „sprich nicht\" mit derselben Form wie im Bejahten; hier hilft das Sprachgefühl nicht. Die übrigen Personen bekommen einfach non + Form.</p><p>Kurze unregelmäßige du-Formen: <em>fa' (fai), da' (dai), sta' (stai), va' (vai), di' (dici)</em>. Ein folgendes Pronomen verdoppelt den Konsonanten: <em>dammi, fallo, dimmi, vattene</em> (außer <em>gli</em> — <em>digli</em>).</p><p>Die Pronomen hängen sich an die Formen von tu/noi/voi an (<em>prendilo, andiamoci, ascoltatemi</em>) und stehen vor der Höflichkeitsform (<em>lo prenda, mi ascolti</em>).</p>"
  },
  "ref:g-gerundio": {
    title: "Gerundio und stare + gerundio",
    sub: "die Verlaufsform und implizite Sätze",
    body: "<p>Gerundio: <em>-are → -ando</em>, <em>-ere/-ire → -endo</em>. Unregelmäßig: <em>facendo, dicendo, bevendo, traducendo, ponendo</em>.</p><p>Deutsch hat dafür keine eigene Form und behilft sich mit Nebensätzen („während ich nach Hause ging\") oder mit „beim\" + Nomen. Das Gerundio erledigt das in einem Wort, und genau darin liegt seine Nützlichkeit für einen deutschen Text, der sonst schwerfällig wird.</p><ul><li><b>stare + gerundio</b> — Handlung im Verlauf, nur jetzt gerade: <em>Sto lavorando.</em> Das rheinische „ich bin am Arbeiten\" trifft es genau, die Standardsprache muss „gerade\" dazusetzen.</li><li>Begleitumstand: <em>Camminando, ho incontrato Marco.</em></li><li>Art und Weise: <em>Ho imparato l'italiano guardando film.</em></li><li>Grund: <em>Essendo stanco, sono rimasto a casa.</em></li><li>Bedingung: <em>Studiando di più, passeresti l'esame.</em></li></ul><p>Das Gerundio verlangt <b>dasselbe Subjekt</b> wie der Hauptsatz. Sonst braucht es einen vollständigen Nebensatz.</p><p><b>Gerundio passato</b> (<em>avendo finito</em>) markiert Vorzeitigkeit: <em>Avendo finito il lavoro, sono uscito.</em></p>"
  },
  "ref:g-infinito": {
    title: "Der Infinitiv im Nebensatz",
    sub: "di, a, per + Infinitiv",
    body: "<p>Haben beide Sätze dasselbe Subjekt, steht ein Infinitiv statt eines <em>che</em>-Satzes. Deutsch macht dasselbe mit „zu\" + Infinitiv, nur dass Italienisch je nach Verb zwischen drei Präpositionen wählt.</p><ul><li><b>di</b>: <em>penso di partire, spero di vederti, ho paura di sbagliare, finire di, smettere di, cercare di</em></li><li><b>a</b>: <em>comincio a capire, imparo a nuotare, riesco a farlo, aiutare a, provare a, continuare a</em></li><li><b>per</b> (Zweck): <em>studio per imparare</em> — „um zu lernen\"</li><li>ohne Präposition nach den Modalverben und nach <em>preferire, desiderare, sapere, far fare, lasciare</em></li></ul><p class='callout callout--trap'>Der Infinitiv steht <b>nicht</b> am Satzende. <em>Voglio andare a Roma domani</em>, nicht „*voglio a Roma domani andare\". Die deutsche Klammer ist der zähste Reflex beim Satzbau.</p><p><b>Infinito passato</b>: <em>dopo aver mangiato</em>, <em>dopo essere uscito</em> — nach <em>dopo</em> immer, wie „nachdem ich gegessen hatte\", nur ohne Nebensatz.</p>"
  },
  "ref:g-passivo": {
    title: "Das Passiv",
    sub: "essere, venire, andare, si passivante",
    body: "<ul><li><b>essere</b> + Partizip — das allgemeine: <em>La lettera è stata scritta da Marco.</em> Entspricht dem Zustandspassiv mit „sein\".</li><li><b>venire</b> + Partizip — nur in einfachen Zeiten, betont den Vorgang: <em>La legge viene approvata ogni anno.</em> Das ist genau der Unterschied zwischen deutschem Vorgangspassiv („wird verabschiedet\") und Zustandspassiv („ist verabschiedet\"). Diese Unterscheidung bringst du mit.</li><li><b>andare</b> + Partizip — drückt <b>Notwendigkeit</b> aus: <em>Il modulo va compilato in stampatello</em> = das Formular muss ausgefüllt werden. Das deutsche „ist auszufüllen\" trifft es gut. Als gewöhnliches Passiv gelesen, kippt der Sinn.</li><li><b>si passivante</b> — im Gespräch am häufigsten: <em>Qui si vendono panini.</em> Das Verb richtet sich nach der verkauften Sache.</li></ul><p>Der Urheber wird mit <em>da</em> eingeführt: <em>è stato fatto <b>da</b> loro</em>. Nur transitive Verben bilden ein Passiv.</p>"
  },
  "ref:g-participio": {
    title: "Partizip Präsens und Perfekt",
    sub: "als Adjektiv, Nomen und Verb",
    body: "<p><b>Participio presente</b> (<em>-ante, -ente</em>) arbeitet selten als Verb, oft als Adjektiv oder Nomen: <em>brillante, insegnante, cantante, dirigente</em>. Deutsch hat dieselben Erstarrungen („glänzend\", „der Vorsitzende\"). Der verbale Gebrauch überlebt in der Rechtssprache: <em>il denaro <b>derivante</b> dalle offerte sarà investito</em>.</p><p class='callout callout--trap'>Was Italienisch <b>nicht</b> hat, ist das erweiterte Partizipialattribut vor dem Nomen: „die aus den Spenden stammenden Gelder\" lässt sich nicht nachbauen. Man löst es in einen Relativsatz auf oder benutzt genau dieses <em>derivante</em> nachgestellt.</p><p><b>Participio passato</b> in verkürzten Sätzen ersetzt einen Temporal- oder Kausalsatz: <em><b>Prenotato</b> il viaggio, puoi partire tranquillo.</em> <em><b>Finita</b> la riunione, sono uscito.</em> Das Partizip richtet sich dabei nach dem Nomen, auf das es sich bezieht.</p><p>Als Adjektiv und Nomen: <em>apprezzato, pentito, il ferito, i laureati</em>.</p>"
  },
  "ref:g-perifrasi": {
    title: "Verbalperiphrasen",
    sub: "sto per, va rivisto, ho da fare",
    body: "<ul><li><b>aspektuell</b>: <em>sto per partire</em> (ich bin im Begriff zu gehen), <em>mi accingo a</em>, <em>sono sul punto di</em>, <em>comincio a</em>, <em>continuo a</em>, <em>smetto di</em>, <em>finisco di</em></li><li><b>modal</b>: <em>il compito <b>va</b> rivisto</em> (die Aufgabe ist zu überarbeiten), <em><b>ho da</b> studiare</em> (ich habe zu lernen), <em>c'è da fare</em> — das deutsche „haben + zu\" deckt sich hier fast wörtlich</li><li><b>gerundial</b>: <em>sta cadendo</em> (es fällt gerade), <em>va crescendo</em> (nimmt allmählich zu, Schriftsprache)</li><li><b>kausativ</b>: <em>far fare qualcosa a qualcuno</em> — „etwas machen lassen\". Achtung: die Person, die es tut, steht mit <em>a</em>, nicht im Akkusativ.</li></ul>"
  },
  "ref:g-preposizioni": {
    title: "Einfache und zusammengezogene Präpositionen",
    sub: "di, a, da, in, su, con, per, tra/fra",
    body: "<div class='table-wrap'><table class='gt'><thead><tr><th></th><th>il</th><th>lo</th><th>la</th><th>l'</th><th>i</th><th>gli</th><th>le</th></tr></thead><tbody><tr><td>di</td><td class='it'>del</td><td>dello</td><td>della</td><td>dell'</td><td>dei</td><td>degli</td><td>delle</td></tr><tr><td>a</td><td class='it'>al</td><td>allo</td><td>alla</td><td>all'</td><td>ai</td><td>agli</td><td>alle</td></tr><tr><td>da</td><td class='it'>dal</td><td>dallo</td><td>dalla</td><td>dall'</td><td>dai</td><td>dagli</td><td>dalle</td></tr><tr><td>in</td><td class='it'>nel</td><td>nello</td><td>nella</td><td>nell'</td><td>nei</td><td>negli</td><td>nelle</td></tr><tr><td>su</td><td class='it'>sul</td><td>sullo</td><td>sulla</td><td>sull'</td><td>sui</td><td>sugli</td><td>sulle</td></tr></tbody></table></div><p>Deutsch zieht auch zusammen („zum\", „im\", „ans\"), aber nur gelegentlich und ohne System. Italienisch tut es durchgehend und verbindlich: <em>a il</em> gibt es nicht, es muss <em>al</em> heißen.</p><p><em>con</em>, <em>per</em> und <em>tra/fra</em> werden nicht zusammengezogen (bis auf das seltene <em>col</em>).</p><h4>Ort: a oder in</h4><p>Die deutsche Wechselpräposition mit Akkusativ und Dativ hat hier keine Entsprechung: Richtung und Ort werden <b>nicht</b> unterschieden. <em>Vado a Roma</em> und <em>sono a Roma</em> nehmen dieselbe Präposition. Was bleibt, ist eine Liste.</p><ul><li><b>a</b>: Städte (<em>a Roma</em>), <em>a casa, a scuola, a letto, al mare, al cinema, al lavoro</em></li><li><b>in</b>: Länder und Regionen (<em>in Italia, in Toscana</em>), <em>in centro, in ufficio, in banca, in montagna, in vacanza</em>, Verkehrsmittel (<em>in treno, in macchina</em>)</li><li><b>da</b>: „bei\" und „von\" bei Personen (<em>vado dal medico, vengo da Marco</em>)</li></ul>"
  },
  "ref:g-prep-verbi": {
    title: "Präpositionen, die das Verb verlangt",
    sub: "eine Liste, die man einfach lernt",
    body: "<p>Die Präposition nach einem Verb ist nicht logisch, sie ist lexikalisch — genau wie „warten <b>auf</b>\" oder „denken <b>an</b>\" im Deutschen. Man lernt sie mit dem Verb und erwartet nicht, dass sie zur deutschen passt.</p><h4>+ di</h4><p><em>finire di, smettere di, cercare di, decidere di, dimenticare di, ricordarsi di, accorgersi di, avere bisogno di, avere paura di, pensare di, sperare di, accettare di, promettere di, evitare di</em></p><h4>+ a</h4><p><em>cominciare a, iniziare a, continuare a, imparare a, riuscire a, provare a, aiutare a, insegnare a, abituarsi a, rinunciare a, pensare a (denken an), servire a</em></p><h4>ohne Präposition</h4><p><em>potere, volere, dovere, sapere, preferire, desiderare, amare, osare, far fare, lasciare, vedere, sentire</em></p><p class='callout callout--trap'><b>pensare a</b> (an etwas denken) gegen <b>pensare di</b> (beabsichtigen oder eine Meinung haben). <em>Penso a te</em> ≠ <em>Penso di partire</em>. Und <em>aspettare</em> steht ohne Präposition, wo Deutsch „warten auf\" verlangt.</p>"
  },
  "ref:g-avverbi": {
    title: "Die Adverbien",
    sub: "Bildung, Stellung, Fokusadverbien",
    body: "<p>Vom Adjektiv: feminine Form + <em>-mente</em> (<em>lenta → lentamente</em>). Deutsch braucht dafür gar nichts: dort ist das Adverb formgleich mit dem Adjektiv („langsam\"). Im Italienischen muss die Endung mitgedacht werden.</p><p><b>Stellung</b>: Häufigkeitsadverbien stehen direkt hinter dem konjugierten Verb (<em>vado <b>spesso</b> al cinema</em>). In zusammengesetzten Zeiten stehen <em>già, mai, ancora, sempre, appena</em> <b>zwischen Hilfsverb und Partizip</b>: <em>ho <b>già</b> mangiato</em>, <em>non sono <b>mai</b> stato</em> — dieselbe Stelle wie im deutschen „ich habe schon gegessen\".</p><p><b>Fokusadverbien</b> (B2): <em>anche, pure, solo, soltanto, perfino, addirittura, soprattutto, specialmente, proprio, neanche, nemmeno, neppure</em> — die Bedeutung verschiebt sich mit dem, wovor sie stehen. Das kennst du von „nur\", „sogar\", „auch\".</p><p><b>Buono/bene</b>: <em>buono</em> ist das Adjektiv, <em>bene</em> das Adverb — „gut\" deckt im Deutschen beides ab, deshalb wird es hier gern verwechselt. <em>Un caffè buono</em> gegen <em>parla bene</em>.</p>"
  },
  "ref:g-connettivi": {
    title: "Textkonnektoren",
    sub: "was Rede und Aufsatz zusammenhält",
    body: "<div class='table-wrap'><table class='gt'><thead><tr><th>Funktion</th><th>Konnektoren</th></tr></thead><tbody><tr><td>hinzufügen</td><td class='it'>inoltre, in più, anche, per di più, oltre a ciò</td></tr><tr><td>Gegensatz</td><td class='it'>però, tuttavia, invece, al contrario, anzi, d'altra parte, nondimeno</td></tr><tr><td>Grund</td><td class='it'>perché, poiché, siccome, dato che, visto che, in quanto</td></tr><tr><td>Folge</td><td class='it'>quindi, perciò, dunque, di conseguenza, pertanto</td></tr><tr><td>Erklärung</td><td class='it'>cioè, ovvero, vale a dire, in altre parole, in effetti</td></tr><tr><td>Reihenfolge</td><td class='it'>anzitutto, in primo luogo, in secondo luogo, infine, per concludere</td></tr><tr><td>Zusammenfassung</td><td class='it'>insomma, in conclusione, tutto sommato</td></tr></tbody></table></div><p class='callout callout--trap'>Italienische Konnektoren ändern die Wortstellung <b>nicht</b>. Nach <em>quindi</em> und <em>perciò</em> bleibt Subjekt-Verb, während „deshalb\" und „trotzdem\" im Deutschen die Inversion auslösen. Und nach <em>perché</em> und <em>poiché</em> wandert das Verb nicht ans Ende.</p><p><b>Gesprächspartikeln</b>: <em>ecco, allora, niente, insomma, no?, vedi, capirai, guarda, senti, dai</em>. Sie tragen keinen Inhalt, aber ohne sie klingt man vorgelesen — die Funktion von „also\", „halt\", „ja\", „eben\".</p>"
  },
  "ref:g-frase": {
    title: "Wortstellung, Fragen, Verneinung",
    sub: "wie ein Satz gebaut wird",
    body: "<p>Grundfolge: <b>Subjekt – Verb – Objekt</b>, wobei das Subjekt meist wegfällt.</p><p class='callout callout--trap'>Das ist der Punkt, an dem deutschsprachige Lernende am meisten umlernen müssen. Es gibt <b>keine Verbklammer</b> und <b>kein Verb am Nebensatzende</b>: das konjugierte Verb steht an zweiter Stelle, das Partizip und der Infinitiv folgen direkt darauf, im Haupt- wie im Nebensatz. <em>Dico che ho comprato il libro ieri</em> — nicht „*che ieri das Buch gekauft habe\".</p><p><b>Fragen</b> ändern die Wortstellung nicht: Intonation oder ein Fragewort genügt. <em>Parli italiano?</em>, <em>Dove abiti?</em> Keine Inversion nötig, anders als im Deutschen.</p><p><b>Verneinung</b>: <em>non</em> vor dem Verb. Die doppelte Verneinung ist korrekt und verpflichtend, anders als im Deutschen, wo sie als Fehler gilt: <em>Non ho <b>mai</b> visto <b>niente</b> di simile</em> heißt wörtlich „ich habe nicht nie nichts Ähnliches gesehen\" und ist genau richtig so. Steht das Negationswort vor dem Verb, fällt <em>non</em> weg: <em><b>Nessuno</b> è venuto.</em></p><p>Fragewörter: <em>chi, che cosa, dove, quando, come, perché, quale, quanto</em>. Achtung bei <em>dov'è</em>, <em>com'è</em>, <em>qual è</em> (letzteres ohne Apostroph).</p>"
  },
  "ref:g-discorso-indiretto": {
    title: "Die indirekte Rede",
    sub: "Verschiebung der Zeiten und Angaben",
    body: "<div class='table-wrap'><table class='gt'><thead><tr><th>direkte Rede</th><th>indirekt (nach Vergangenheit)</th></tr></thead><tbody><tr><td>presente</td><td class='it'>imperfetto</td></tr><tr><td>passato prossimo / remoto</td><td class='it'>trapassato prossimo</td></tr><tr><td>futuro</td><td class='it'>condizionale passato</td></tr><tr><td>imperativo</td><td class='it'>di + infinito</td></tr><tr><td>congiuntivo presente</td><td class='it'>congiuntivo imperfetto</td></tr></tbody></table></div><p class='callout callout--trap'>Hier trennen sich die Wege grundsätzlich. Deutsch markiert die indirekte Rede mit dem <b>Konjunktiv I</b> und lässt die Zeitstufe stehen („er sagte, er sei müde\"). Italienisch benutzt den <b>Indikativ</b> und verschiebt stattdessen die Zeiten. Wer nach deutschem Muster einen Konjunktiv sucht, greift zur falschen Kategorie.</p><p>Zeit- und Ortsangaben verschieben sich mit: <em>oggi → quel giorno, domani → il giorno dopo, ieri → il giorno prima, qui → lì, questo → quello, adesso → allora</em>.</p><p><em>„Verrò domani\" → Disse che <b>sarebbe venuto il giorno dopo</b>.</em> Die Zukunft aus der Vergangenheit verlangt den <b>zusammengesetzten</b> Konditional.</p>"
  },
  "ref:g-registri": {
    title: "Register und Stil",
    sub: "formell, umgangssprachlich, behördlich",
    body: "<p><b>Formelles Italienisch</b>: das Passiv, Nominalisierungen (<em>l'approvazione della legge</em>), <em>Lei</em>, latinisierender Wortschatz (<em>effettuare</em> statt <em>fare</em>), Vermeidung pronominaler Verben.</p><p><b>Gesprochenes Italienisch / Neostandard</b>: <em>lui/lei</em> als Subjekt, <em>gli</em> für <em>loro</em>, das Allzweck-<em>che</em> (<em>il giorno che sono arrivato</em>), Dislokation (<em>il libro, l'ho letto</em>), Imperfetto statt Konjunktiv in Bedingungssätzen.</p><p><b>Burocratese</b>: <em>di cui sopra, ai sensi di, in ottemperanza a, si comunica che, il sottoscritto</em>. Auf C1 zählt es mehr, das <i>lesen</i> zu können als es zu schreiben. Das deutsche Amtsdeutsch pflegt dieselben Marotten — Nominalstil, Passiv, Verweisformeln — und wird mit denselben Argumenten bekämpft.</p><p><b>Dislokation</b> als Werkzeug: <em>A Roma non ci sono mai stato</em> rückt das Gewicht an den Satzanfang. Das ist keine Nachlässigkeit, sondern lebendiges Italienisch, und funktional dasselbe wie das deutsche Vorfeld: „nach Rom bin ich nie gekommen\".</p>"
  },
  "ref:g-fonologia": {
    title: "Aussprache und Rechtschreibung",
    sub: "c, g, gl, gn, Doppelkonsonanten, Betonung",
    body: "<p>Zuerst die gute Nachricht: die italienische Rechtschreibung ist regelmäßig. Wer die Regeln kennt, liest jedes Wort richtig vor.</p><h4>C und G</h4><p>Vor <em>a, o, u</em> hart: <em>casa, gatto</em>. Vor <em>e, i</em> weich: <em>cena</em> („tschena\"), <em>gelato</em> („dschelato\"). Ein <b>h</b> stellt den harten Laut wieder her: <em>chiesa</em> („kiesa\"), <em>ghiaccio</em>. Ein <b>i</b> macht weich, ohne selbst gesprochen zu werden: <em>ciao</em> („tschau\"), <em>giorno</em> („dschorno\").</p><h4>Besondere Gruppen</h4><ul><li><b>gn</b> = wie in „Champignon\": <em>gnocchi, bagno, signore</em></li><li><b>gl</b> + i = ein Laut, den Deutsch nicht hat, etwa wie das ll in „Million\": <em>famiglia, figlio, aglio</em>; aber <em>glicine, negligente</em> werden g+l gelesen</li><li><b>sc</b> vor e/i = „sch\": <em>pesce, sciare</em>; vor a/o/u = sk: <em>scala, scuola</em></li><li><b>z</b> = ts oder dz: <em>pizza</em> („pittsa\"), <em>zero</em> („dsero\") — das ts kennst du aus „Zeit\"</li><li><b>s</b> zwischen Vokalen wird stimmhaft wie in „Rose\": <em>casa</em>, <em>rosa</em></li></ul><h4>Doppelkonsonanten</h4><p class='callout callout--trap'>Im Deutschen zeigt ein Doppelkonsonant an, dass der <b>Vokal davor kurz</b> ist; gesprochen wird er nur einmal. Im Italienischen wird er <b>wirklich gehalten</b>, und er unterscheidet Wörter: <em>casa</em> (Haus) / <em>cassa</em> (Kiste), <em>pala</em> (Schaufel) / <em>palla</em> (Ball), <em>nono</em> (neunter) / <em>nonno</em> (Großvater). Die deutsche Lesegewohnheit führt hier direkt zum Missverständnis.</p><h4>Betonung</h4><p>Meist auf der vorletzten Silbe. Der geschriebene Akzent am Wortende ist Pflicht: <em>città, perché, caffè, così, più</em>. Achtung bei Wörtern mit Betonung auf der drittletzten Silbe: <em><b>abi</b>tano, <b>tele</b>fono, <b>por</b>tami</em>. Und: es gibt keinen Knacklaut vor Vokalen — <em>un'amica</em> wird gebunden gesprochen, nicht abgesetzt wie „ein | Apfel\".</p>"
  }
});
